/// <summary>
/// lookup for chain groups
/// </summary>
/// <param name = "_lookupCtrl">Formstringcontrol</param>
public static void lookup(FormStringControl _lookupCtrl)
{
    Query                   query = new Query();
    QueryBuildDataSource    queryBuildDataSource = query.addDataSource(tableNum(smmBusRelChainGroup));

    queryBuildDataSource.addSortField(fieldNum(smmBusRelChainGroup, ChainId), SortOrder::Ascending);

    SysTableLookup  sysTableLookup  = SysTableLookup::newParameters(tableNum(smmBusRelChainGroup), _lookupCtrl);

    sysTableLookup.addLookupfield(fieldNum(smmBusRelChainGroup, ChainId));
    sysTableLookup.addLookupfield(fieldNum(smmBusRelChainGroup, Description));

    sysTableLookup.parmQuery(query);
    sysTableLookup.performFormLookup();
}

/// <summary>
/// Find Record by RecID
/// </summary>
/// <param name = "_recordId">RecId of record</param>
/// <param name = "_forUpdate">true or false</param>
/// <returns>smmBusRelChainGroup record</returns>
public static smmBusRelChainGroup findByRecId(RecId _recordId, boolean _forUpdate = false)
{
    smmBusRelChainGroup record;

    if (_recordId)
    {
        record.selectForUpdate(_forUpdate);

        select firstonly record
            where record.RecId == _recordId;
    }

    return record;
}
